t.script:
                (function () {
                    'use strict';
                    var list = document.getElementById('ccList'), T = list.getAttribute('data-token'),
                        textEl = document.getElementById('ccText'),
                        btn = document.getElementById('ccSend'), err = document.getElementById('ccErr'),
                        pin = document.getElementById('ccPin'), menu = document.getElementById('ccMenu'),
                        chips = document.getElementById('ccChips'), replyBar = document.getElementById('ccReply'),
                        prog = document.getElementById('ccProg'), scrim = document.getElementById('ccScrim'),
                        card = document.getElementById('ccCard');
                    var MAX_FILES = 10, MAX_BYTES = 50 * 1024 * 1024;
                    var QUICK = ['👍', '❤️', '😂', '😮', '😢', '🙏'];
                    var ALL = ['👍', '👎', '❤️', '🔥', '🎉', '👏', '🙏', '💯', '😂', '🤣', '😅', '😊', '😍', '😎', '🤔', '😐',
                               '😮', '😢', '😭', '😡', '🥳', '🤝', '💪', '✅', '❌', '⚠️', '👀', '🚀', '⭐', '💡', '⏰', '📌'];
                    var picked = [], replyTo = null, editing = null, sending = false, shown = '', rowsNow = [];
                    // This page has no login, so reactions / edits are keyed by a
                    // browser id made once here (the server sees it as 'c:<id>').
                    var WHO = (function () {
                        var key = 'kpiChatWho', id = '';
                        try { id = localStorage.getItem(key) || ''; } catch (e) { id = ''; }
                        if (!/^c:[A-Za-z0-9_-]{8,40}$/.test(id)) {
                            var a = new Uint8Array(12), s = '';
                            (window.crypto || window.msCrypto).getRandomValues(a);
                            for (var i = 0; i < a.length; i++) { s += ('0' + a[i].toString(16)).slice(-2); }
                            id = 'c:' + s;
                            try { localStorage.setItem(key, id); } catch (e) { /* kept in memory only */ }
                        }
                        return id;
                    })();
                    function el(tag, cls, text) {
                        var e = document.createElement(tag);
                        if (cls) { e.className = cls; }
                        if (text != null) { e.textContent = text; }
                        return e;
                    }
                    function date(utc) { var d = new Date((utc || '').replace(' ', 'T') + 'Z'); return isNaN(d) ? null : d; }
                    function day(d) {
                        var k = d.toDateString();
                        if (k === new Date().toDateString()) { return 'Today'; }
                        if (k === new Date(Date.now() - 864e5).toDateString()) { return 'Yesterday'; }
                        return d.toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' });
                    }
                    function clock(d) { return d ? d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : ''; }
                    function when(utc) { var d = date(utc); return d ? (day(d) === 'Today' ? '' : day(d) + ' ') + clock(d) : 'not yet'; }
                    function size(n) {
                        n = n || 0;
                        if (n < 1024) { return n + ' B'; }
                        if (n < 1048576) { return (n / 1024).toFixed(0) + ' KB'; }
                        return (n / 1048576).toFixed(1) + ' MB';
                    }
                    function kindOf(f) {
                        var t = (f.type || '').toLowerCase(), n = (f.name || '').toLowerCase();
                        if (t.indexOf('audio/') === 0) { return 'audio'; }
                        if (t.indexOf('image/') === 0) { return 'image'; }
                        if (t.indexOf('video/') === 0) { return 'video'; }
                        if (/\.(jpe?g|png|gif|webp|bmp|heic|heif)$/.test(n)) { return 'image'; }
                        if (/\.(mp4|mov|mkv|avi|m4v)$/.test(n)) { return 'video'; }
                        if (/\.(webm|ogg|opus|mp3|wav|m4a|aac|amr|3gp)$/.test(n)) { return 'audio'; }
                        if (/\.(pdf|docx?|xlsx?|pptx?|odt|ods|odp|rtf|txt|csv|zip|rar|7z)$/.test(n)) { return 'document'; }
                        return '';
                    }
                    var ICON = { image: '📷', video: '🎥', audio: '🎵', document: '📄' };
                    function filesLabel(files) {
                        var out = [];
                        [['image', 'photo', 'photos'], ['video', 'video', 'videos'], ['audio', 'audio', 'audios'], ['document', 'document', 'documents']].forEach(function (k) {
                            var n = (files || []).filter(function (f) { return f.kind === k[0]; }).length;
                            if (n) { out.push(ICON[k[0]] + ' ' + n + ' ' + (n === 1 ? k[1] : k[2])); }
                        });
                        return out.join(' · ');
                    }
                    function showErr(msg) { err.textContent = msg; err.hidden = !msg; }
// Online = on screen and touched in the last minute; the server tells
                    // the other side's WhatsApp to stay quiet while we are online.
                    var lastTouch = Date.now();
                    ['pointerdown', 'keydown', 'touchstart', 'scroll', 'wheel', 'mousemove'].forEach(function (n) {
                        document.addEventListener(n, function () { lastTouch = Date.now(); }, { passive: true, capture: true });
                    });
                    function isActive() { return document.visibilityState === 'visible' && Date.now() - lastTouch < 60000; }
                    // 🔒 Not confirmed yet: one tap on a pre-typed WhatsApp message to our
                    // number proves this phone / laptop belongs to the client. Once.
                    var lockEl = document.getElementById('ccLock'), rowEl = document.querySelector('.cc-row');
                    function showLock(res) {
                        list.hidden = true; rowEl.hidden = true; lockEl.hidden = false;
                        var c = res.confirm || {};
                        var key = c.nonce || '-';
                        if (lockEl.getAttribute('data-key') === key) { return; }
                        lockEl.setAttribute('data-key', key);
                        lockEl.textContent = '';
                        lockEl.appendChild(el('div', '', '🔒'));
                        lockEl.appendChild(el('b', '', 'Confirm it’s you'));
                        lockEl.appendChild(el('p', '', 'This chat is only for ' + (res.client || 'the client') +
                            ' and its developer. Confirm once on WhatsApp — after that this phone or computer opens your chats straight away.'));
                        if (c.url) {
                            var a = el('a', 'cc-go', '✅ Confirm on WhatsApp'); a.href = c.url; a.target = '_blank'; a.rel = 'noopener';
                            lockEl.appendChild(a);
                            lockEl.appendChild(el('p', '', 'WhatsApp opens with this message already typed — just tap Send:'));
                            lockEl.appendChild(el('span', 'cc-typed', c.text));
                            var q = el('div', 'cc-qr');
                            q.appendChild(el('p', '', 'On a computer without WhatsApp? Scan this with your phone:'));
                            var img = el('img'); img.alt = 'QR code';
                            img.src = '/report/barcode/QR/' + encodeURIComponent(c.url) + '?width=400&height=400';
                            q.appendChild(img);
                            lockEl.appendChild(q);
                        } else {
                            lockEl.appendChild(el('p', '', 'Please ask the Alphalize team to send you the chat again.'));
                        }
                        lockEl.appendChild(el('p', '', 'This page opens the chat by itself once you have sent it.'));
                    }
                    function hideLock() {
                        if (lockEl.hidden) { return; }
                        lockEl.hidden = true; list.hidden = false; rowEl.hidden = false; shown = '';
                    }
                    function rpc(path, params) {
                        var p = params || {};
                        p.who = WHO;
                        return fetch('/kpi/wa/chat/' + T + path, { method: 'POST', headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: p }) })
                            .then(function (r) { return r.json(); })
                            .then(function (d) { var res = (d && d.result) || {}; if (res.expired) { location.reload(); } return res; });
                    }

                    // ---- the thread: date on top of each day, time on each message
                    function media(f, r) {
                        var box = el('div', 'cc-file'), m;
                        if (f.kind === 'document') {
                            m = el('a'); m.href = f.url; m.target = '_blank'; m.rel = 'noopener';
                            m.style.cssText = 'display:flex;gap:8px;align-items:center;padding:10px 12px;background:rgba(0,0,0,.05);border-radius:6px;color:inherit;text-decoration:none;word-break:break-all;min-width:200px';
                            m.appendChild(el('span', '', '📄')); m.appendChild(el('b', '', f.name));
                            box.appendChild(m); box.appendChild(el('div', 'cc-fname', size(f.size)));
                            return box;
                        }
                        if (f.kind === 'image') {
                            m = el('img'); m.src = f.url; m.alt = f.name; m.loading = 'lazy';
                            m.addEventListener('click', function () { viewPhoto(f, r); });
                            box.appendChild(m);
                        } else {
                            m = el(f.kind === 'video' ? 'video' : 'audio');
                            m.src = f.url; m.controls = true; m.preload = 'metadata';
                            box.appendChild(m);
                        }
                        box.appendChild(el('div', 'cc-fname', f.name + ' · ' + size(f.size)));
                        return box;
                    }
                    // Tap a photo: full screen over the chat, as in WhatsApp. ✕, a tap
                    // outside the photo or Esc closes it.
                    // r: the message it came in. Who sent it and when on top; its words under
                    // the photo, as in WhatsApp.
                    function pvHead(f, r) {
                        var h = el('span', 'pv-name'), t = r ? date(r.at) : null;
                        h.appendChild(el('b', '', (r ? r.who : '') || f.name));
                        if (t) { h.appendChild(el('small', '', (day(t) === 'Today' ? 'Today' : day(t)) + ' at ' + clock(t))); }
                        return h;
                    }
                    function viewPhoto(f, r) {
                        var v = el('div', 'pv-shade'), img = el('img'), bar = el('div', 'pv-bar'), x = el('button', 'pv-x', '✕');
                        var dl = el('a', 'pv-dl', '⤓'); dl.href = f.url; dl.target = '_blank'; dl.title = 'Open / download';
                        x.type = 'button'; x.title = 'Close';
                        bar.appendChild(pvHead(f, r)); bar.appendChild(dl); bar.appendChild(x);
                        img.src = f.url; img.alt = f.name;
                        v.appendChild(bar); v.appendChild(img);
                        if (r ? r.body : '') { v.appendChild(el('div', 'pv-cap', r.body)); }
                        function shut() { document.removeEventListener('keydown', key); if (v.parentNode) { v.parentNode.removeChild(v); } }
                        function key(e) { if (e.key === 'Escape') { shut(); } }
                        x.addEventListener('click', shut);
                        v.addEventListener('click', function (e) { if (e.target === v) { shut(); } });
                        document.addEventListener('keydown', key);
                        document.body.appendChild(v);
                    }
                    function jump(id) {
                        var t = document.getElementById('cc-m' + id);
                        if (!t) { return; }
                        t.scrollIntoView({ block: 'center', behavior: 'smooth' });
                        t.classList.add('flash');
                        setTimeout(function () { t.classList.remove('flash'); }, 1400);
                    }
                    // ✓ saved · ✓✓ reached our team · blue ✓✓ our team opened the chat ·
                    // ⚠ it did not go through (tap to retry): on the client's own bubbles.
                    function tick(r) {
                        var t = el('span', 'cc-tick', r.status === 'failed' ? ' ⚠' : (r.status === 'pending' ? ' ✓' : ' ✓✓'));
                        t.style.color = r.status === 'seen' ? '#53bdeb' : (r.status === 'failed' ? '#d4572e' : '#667781');
                        t.style.letterSpacing = '-2px';
                        t.title = r.status === 'failed' ? ((r.error || 'Not sent to our team.') + ' Tap to retry.')
                            : r.status === 'seen' ? 'Seen by our team' : r.status === 'sent' ? 'Reached our team' : 'Sending…';
                        if (r.status === 'failed') {
                            t.style.cursor = 'pointer';
                            t.addEventListener('click', function () {
                                rpc('/retry', { message_id: r.id }).then(function (res) {
                                    if (res.ok) { shown = ''; draw(res.rows || []); } else { showErr(res.message || 'Could not retry.'); }
                                });
                            });
                        }
                        return t;
                    }
                    // Hold a bubble (or right-click) to open its actions, as in WhatsApp.
                    function holdable(node, id) {
                        var timer = null, sx = 0, sy = 0, fired = false, firedAt = 0;
                        function clear() { if (timer) { clearTimeout(timer); timer = null; } }
                        function start(x, y) { sx = x; sy = y; fired = false; clear(); timer = setTimeout(function () { timer = null; fired = true; firedAt = Date.now(); openCard(id); }, 450); }
                        function moved(x, y) { if (timer && (Math.abs(x - sx) > 8 || Math.abs(y - sy) > 8)) { clear(); } }
                        // Touch first: a phone may cancel pointer events mid-press, touch events it keeps.
                        node.addEventListener('touchstart', function (e) { var t = e.touches[0]; if (t) { start(t.clientX, t.clientY); } }, { passive: true });
                        node.addEventListener('touchmove', function (e) { var t = e.touches[0]; if (t) { moved(t.clientX, t.clientY); } }, { passive: true });
                        node.addEventListener('touchend', function (e) { clear(); if (fired) { e.preventDefault(); } });
                        node.addEventListener('touchcancel', clear);
                        node.addEventListener('mousedown', function (e) { if (e.button === 0 && !('ontouchstart' in window)) { start(e.clientX, e.clientY); } });
                        node.addEventListener('mousemove', function (e) { moved(e.clientX, e.clientY); });
                        ['mouseup', 'mouseleave'].forEach(function (n) { node.addEventListener(n, clear); });
                        // A phone's own long-press menu comes right after our hold: ignore that one.
                        node.addEventListener('contextmenu', function (e) { e.preventDefault(); clear(); if (Date.now() - firedAt > 800) { openCard(id); } });
                    }
                    function reactionChips(r) {
                        if (!r.reactions || !r.reactions.length) { return null; }
                        var row = el('div', 'cc-react');
                        r.reactions.forEach(function (x) {
                            var c = el('button', 'cc-rchip' + (x.mine ? ' mine' : ''), x.emoji + (x.count > 1 ? ' ' + x.count : ''));
                            c.type = 'button'; c.title = x.mine ? 'You reacted — tap to remove' : 'Tap to react';
                            c.addEventListener('click', function () { act(r.id, 'react', { emoji: x.emoji }); });
                            row.appendChild(c);
                        });
                        return row;
                    }
                    // 🔔 A message from the other side while this tab is in the background (or
                    // the window is not focused): a soft pop and "(N) New message" in the tab
                    // title, cleared when the person comes back. Looking at the chat: silent.
                    var notify = (function () {
                        var ctx = null, unread = 0, base = document.title;
                        function unlock() {
                            if (!ctx) { try { ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { ctx = null; } }
                            if (ctx && ctx.state === 'suspended') { ctx.resume(); }
                        }
                        ['pointerdown', 'keydown', 'touchstart'].forEach(function (n) { document.addEventListener(n, unlock, { passive: true }); });
                        function pop() {
                            if (!ctx) { return; }
                            var t = ctx.currentTime;
                            [[880, 0], [1320, 0.08]].forEach(function (p) {
                                var o = ctx.createOscillator(), g = ctx.createGain();
                                o.type = 'sine'; o.frequency.value = p[0];
                                g.gain.setValueAtTime(0.0001, t + p[1]);
                                g.gain.exponentialRampToValueAtTime(0.12, t + p[1] + 0.012);
                                g.gain.exponentialRampToValueAtTime(0.0001, t + p[1] + 0.1);
                                o.connect(g); g.connect(ctx.destination);
                                o.start(t + p[1]); o.stop(t + p[1] + 0.12);
                            });
                        }
                        function away() { return document.hidden || !document.hasFocus(); }
                        function back() { if (!away() && unread) { unread = 0; document.title = base; } }
                        document.addEventListener('visibilitychange', back);
                        window.addEventListener('focus', back);
                        return function (n) {
                            if (!n || !away()) { return; }
                            unread += n;
                            document.title = '(' + unread + ') New message · ' + base;
                            pop();
                        };
                    })();
                    var lastOther = null;   // newest message id from the other side already shown
                    function heard(rows, other) {
                        var newest = 0, fresh = 0;
                        rows.forEach(function (x) {
                            if (x.side !== other || typeof x.id !== 'number') { return; }
                            if (x.id > newest) { newest = x.id; }
                            if (lastOther !== null && x.id > lastOther) { fresh++; }
                        });
                        if (lastOther !== null && fresh) { notify(fresh); }
                        lastOther = Math.max(lastOther || 0, newest);
                    }
var ICONS = {
                        reply: '<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M10 9V5l-7 7 7 7v-4.1c5 0 8.5 1.6 11 5.1-1-5-4-10-11-11z"/></svg>',
                        smile: '<svg viewBox="0 0 24 24" width="SZ" height="SZ" fill="currentColor"><path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5 7.67 11 8.5 11zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>',
                        down: '<svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor"><path d="M16.59 8.59L12 13.17 7.41 8.59 6 10l6 6 6-6z"/></svg>',
                        clip: '<svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor" style="transform:rotate(45deg)"><path d="M16.5 6v11.5c0 2.21-1.79 4-4 4s-4-1.79-4-4V5c0-1.38 1.12-2.5 2.5-2.5s2.5 1.12 2.5 2.5v10.5c0 .55-.45 1-1 1s-1-.45-1-1V6H10v9.5c0 1.38 1.12 2.5 2.5 2.5s2.5-1.12 2.5-2.5V5c0-2.21-1.79-4-4-4S7 2.79 7 5v12.5c0 3.04 2.46 5.5 5.5 5.5s5.5-2.46 5.5-5.5V6h-1.5z"/></svg>',
                        send: '<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>'
                    };
                    var EMOJI = ['😀', '😂', '😊', '😍', '😘', '🤔', '😅', '😉', '🙂', '😎', '😢', '😭', '😡', '👍', '👎', '🙏',
                                 '👏', '💪', '🤝', '👌', '✌️', '🙌', '❤️', '🔥', '🎉', '✅', '❌', '⚠️', '⭐', '💯', '👀', '🚀',
                                 '💡', '📌', '⏰', '📷', '📎', '📝', '💬', '📞'];
                    // WhatsApp Web: on hover, reply at once or react, beside the bubble.
                    function quick(x, canReply) {
                        var q = el('div', 'cc-quick');
                        if (canReply) {
                            var r = el('button'); r.type = 'button'; r.title = 'Reply'; r.innerHTML = ICONS.reply;
                            r.addEventListener('click', function () { setReply(x); });
                            q.appendChild(r);
                        }
                        var e = el('button'); e.type = 'button'; e.title = 'React'; e.innerHTML = ICONS.smile.replace(/SZ/g, '18');
                        e.addEventListener('click', function () { openCard(x.id); });
                        q.appendChild(e);
                        return q;
                    }
                    // The type bar as in WhatsApp: 😊 emoji panel, 📎 paperclip, round send arrow.
                    (function () {
                        var row = pin.parentNode.parentNode, box = el('div', 'cc-emojibox');
                        var b = el('button', 'cc-icon'); b.type = 'button'; b.title = 'Emoji'; b.innerHTML = ICONS.smile.replace(/SZ/g, '24');
                        var panel = el('div', 'cc-emojis'); panel.style.display = 'none';
                        EMOJI.forEach(function (e) {
                            var x = el('button', '', e); x.type = 'button';
                            x.addEventListener('mousedown', function (ev) { ev.preventDefault(); });
                            x.addEventListener('click', function () {
                                var a = textEl.selectionStart != null ? textEl.selectionStart : textEl.value.length, z = textEl.selectionEnd != null ? textEl.selectionEnd : a;
                                textEl.value = textEl.value.slice(0, a) + e + textEl.value.slice(z);
                                textEl.focus(); textEl.selectionStart = textEl.selectionEnd = a + e.length;
                                textEl.dispatchEvent(new Event('input'));
                            });
                            panel.appendChild(x);
                        });
                        b.addEventListener('click', function () { panel.style.display = panel.style.display === 'none' ? '' : 'none'; });
                        document.addEventListener('click', function (ev) { if (panel.style.display !== 'none' && !box.contains(ev.target)) { panel.style.display = 'none'; } });
                        box.appendChild(b); box.appendChild(panel);
                        row.insertBefore(box, pin.parentNode);
                        pin.innerHTML = ICONS.clip; pin.classList.add('cc-icon');
                        btn.innerHTML = ICONS.send;
                    })();
                    function draw(rows) {
                        rowsNow = rows;
                        heard(rows, 'team');
                        // Redraw only when something changed (a message, a tick, an edit, a
                        // reaction), so a playing video is not cut.
                        var sig = rows.map(function (r) { return r.id + (r.status || '') + '|' + (r.v || ''); }).join(',');
                        if (sig === shown) { return; }
                        var atEnd = list.scrollHeight - list.scrollTop - list.clientHeight < 60 || !shown;
                        shown = sig;
                        list.textContent = '';
                        if (!rows.length) { list.appendChild(el('div', 'cc-empty', 'No messages yet.')); return; }
                        var last = '', prevSide = '';
                        rows.forEach(function (r) {
                            var d = date(r.at), k = d ? day(d) : '';
                            if (k !== last) { list.appendChild(el('div', 'cc-day', k)); last = k; prevSide = ''; }
                            var me = r.side === 'client';
                            var row = el('div', 'cc-line' + (me ? ' me' : ''));
                            row.id = 'cc-m' + r.id;
                            var col = el('div', 'cc-col' + (me ? ' me' : ''));
                            var b = el('div', 'cc-msg' + (me ? ' me' : '') + (r.deleted ? ' gone' : '')
                                       + (r.side !== prevSide ? (me ? ' cc-tail-r' : ' cc-tail-l') : ''));
                            prevSide = r.side;
                            b.appendChild(el('b', '', r.who));
                            if (r.reply) {
                                var q = el('div', 'cc-quote' + (r.reply.side === 'client' ? ' me' : ''));
                                q.appendChild(el('b', '', r.reply.who));
                                q.appendChild(el('span', '', r.reply.text));
                                q.addEventListener('click', function () { jump(r.reply.id); });
                                b.appendChild(q);
                            }
                            if (r.deleted) {
                                b.appendChild(el('div', 'cc-deleted', '⊘ This message was deleted'));
                            } else {
                                (r.files || []).forEach(function (f) { b.appendChild(media(f, r)); });
                                if (r.body) { b.appendChild(el('div', 'cc-body', r.body)); }
                            }
                            var meta = el('small', '', (r.edited ? 'edited · ' : '') + clock(d));
                            if (me && r.status && !r.deleted) { meta.appendChild(tick(r)); }
                            b.appendChild(meta);
                            if (!r.deleted) { holdable(b, r.id); caret(b, r.id); }
                            var bl = el('div', 'cc-bl' + (me ? ' r' : ''));
                            bl.appendChild(b);
                            if (!r.deleted) { bl.appendChild(quick(r, true)); }
                            col.appendChild(bl);
                            var chipsRow = reactionChips(r);
                            if (chipsRow) { col.appendChild(chipsRow); }
                            row.appendChild(col);
                            list.appendChild(row);
                        });
                        if (atEnd) { list.scrollTop = list.scrollHeight; }
                    }
                    // visible: the page is on screen, so the team's messages count as seen.
                    function load() {
                        if (sending) { return; }
                        rpc('/rows', { visible: document.visibilityState === 'visible', active: isActive() })
                            .then(function (res) {
                                if (res.locked) { showLock(res); return; }
                                if (res.ok) { hideLock(); draw(res.rows || []); }
                            });
                    }
                    // A text message shows at once with a single ✓ and the box clears;
                    // the server's rows replace it a moment later.
                    function tempRow(text) {
                        var row = el('div', 'cc-line me'), b = el('div', 'cc-msg me');
                        b.appendChild(el('b', '', 'You'));
                        b.appendChild(el('div', 'cc-body', text));
                        var meta = el('small', '', new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
                        meta.appendChild(tick({ status: 'pending' }));
                        b.appendChild(meta); row.appendChild(b); list.appendChild(row);
                        list.scrollTop = list.scrollHeight;
                        return row;
                    }
                    function unsend(row, text) {
                        if (row && row.parentNode) { row.parentNode.removeChild(row); }
                        textEl.value = text;
                    }

                    // ---- the action card (long-press): reactions, reply, edit, info, copy, delete
                    function rowById(id) {
                        for (var i = 0; i < rowsNow.length; i++) { if (rowsNow[i].id === id) { return rowsNow[i]; } }
                        return null;
                    }
                    function closeCard() { scrim.hidden = true; card.textContent = ''; }
                    function act(id, action, extra) {
                        var p = { msg_id: id, action: action };
                        if (extra && extra.emoji) { p.emoji = extra.emoji; }
                        if (extra && extra.text != null) { p.text = extra.text; }
                        return rpc('/act', p).then(function (res) {
                            if (!res.ok) { showErr(res.message || 'That did not work.'); return false; }
                            showErr(''); shown = ''; draw(res.rows || []); return true;
                        }).catch(function () { showErr('No connection — try again.'); return false; });
                    }
                    function emojiButton(id, e) {
                        var b = el('button', 'cc-remoji', e); b.type = 'button';
                        b.addEventListener('click', function () { closeCard(); act(id, 'react', { emoji: e }); });
                        return b;
                    }
                    function actionRow(icon, label, fn, danger) {
                        var b = el('button', 'cc-act' + (danger ? ' danger' : ''));
                        b.type = 'button';
                        b.appendChild(el('span', 'cc-aicon', icon));
                        b.appendChild(el('span', '', label));
                        b.addEventListener('click', function () { closeCard(); fn(); });
                        return b;
                    }
                    function copyText(text) {
                        if (navigator.clipboard && navigator.clipboard.writeText) {
                            navigator.clipboard.writeText(text).catch(function () { fallbackCopy(text); });
                        } else { fallbackCopy(text); }
                    }
                    function fallbackCopy(text) {
                        var ta = el('textarea'); ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
                        document.body.appendChild(ta); ta.select();
                        try { document.execCommand('copy'); } catch (e) { /* nothing to do */ }
                        document.body.removeChild(ta);
                    }
                    // ⌄ on a bubble when the mouse is over it (as WhatsApp Web): opens the actions.
                    function caret(b, id) {
                        var c = el('button', 'cc-caret'); c.innerHTML = ICONS.down;
                        c.type = 'button'; c.title = 'Message options';
                        c.addEventListener('mousedown', function (e) { e.stopPropagation(); });
                        c.addEventListener('touchstart', function (e) { e.stopPropagation(); }, { passive: true });
                        c.addEventListener('click', function (e) { e.stopPropagation(); openCard(id); });
                        b.appendChild(c);
                    }
                    // Info: when it was sent, reached the other side and was seen. Plain times.
                    function infoList(box, events) {
                        events.forEach(function (ev) {
                            var d = ev[2] ? new Date(ev[2].replace(' ', 'T') + 'Z') : null;
                            var when = 'not yet';
                            if (d && !isNaN(d)) {
                                when = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                                if (d.toDateString() !== new Date().toDateString()) {
                                    when = d.toLocaleDateString([], { day: 'numeric', month: 'short' }) + ', ' + when;
                                }
                            }
                            var row = el('div', 'cc-irow' + (ev[3] ? ' ' + ev[3] : ''));
                            row.appendChild(el('span', 'cc-imark', ev[0]));
                            row.appendChild(el('span', 'cc-iwhat', ev[1]));
                            row.appendChild(el('span', 'cc-itime', when));
                            box.appendChild(row);
                        });
                    }
                    function showInfo(r) {
                        card.textContent = '';
                        var box = el('div', 'cc-info');
                        box.appendChild(el('b', '', 'Message info'));
                        infoList(box, [['✓', 'Sent', r.at], ['✓✓', 'Reached our team', r.info && r.info.delivered_at],
                                      ['✓✓', 'Seen by our team', r.info && r.info.seen_at, 'seen']]);
                        var x = el('button', 'cc-act', 'Close'); x.type = 'button';
                        x.addEventListener('click', closeCard);
                        box.appendChild(x);
                        card.appendChild(box);
                        scrim.hidden = false;
                    }
                    function openCard(id) {
                        var r = rowById(id);
                        if (!r || r.deleted) { return; }
                        card.textContent = '';
                        var strip = el('div', 'cc-strip');
                        QUICK.forEach(function (e) { strip.appendChild(emojiButton(id, e)); });
                        var more = el('button', 'cc-remoji', '+'); more.type = 'button'; more.title = 'More reactions';
                        more.addEventListener('click', function () {
                            card.textContent = '';
                            var head = el('div', 'cc-ghead');
                            var back = el('button', 'cc-act', '← Back'); back.type = 'button';
                            back.addEventListener('click', function () { openCard(id); });
                            head.appendChild(back); head.appendChild(el('span', '', 'Pick a reaction'));
                            card.appendChild(head);
                            var grid = el('div', 'cc-grid');
                            ALL.forEach(function (e) { grid.appendChild(emojiButton(id, e)); });
                            card.appendChild(grid);
                        });
                        strip.appendChild(more);
                        card.appendChild(strip);
                        var acts = el('div', 'cc-acts');
                        acts.appendChild(actionRow('↩', 'Reply', function () { setReply(r); }));
                        if (r.can_edit) { acts.appendChild(actionRow('✎', 'Edit', function () { setEdit(r); })); }
                        if (r.info) { acts.appendChild(actionRow('ⓘ', 'Info', function () { showInfo(r); })); }
                        if (r.body) { acts.appendChild(actionRow('⎘', 'Copy', function () { copyText(r.body); })); }
                        if (r.can_delete) {
                            acts.appendChild(actionRow('🗑', 'Delete', function () {
                                if (window.confirm('Delete this message for everyone?')) { act(id, 'delete'); }
                            }, true));
                        }
                        card.appendChild(acts);
                        scrim.hidden = false;
                    }
                    scrim.addEventListener('click', function (e) { if (e.target === scrim) { closeCard(); } });
                    document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && !scrim.hidden) { closeCard(); } });

                    // ---- ↩ reply / ✎ edit: the bar above the box
                    function setReply(r) {
                        replyTo = r ? r.id : null;
                        editing = null;
                        replyBar.textContent = '';
                        replyBar.hidden = !r;
                        if (!r) { return; }
                        var t = el('div', 'cc-rtext');
                        t.appendChild(el('b', '', '↩ Replying to ' + r.who));
                        t.appendChild(el('span', '', (r.body || '').replace(/\s+/g, ' ').slice(0, 120) || filesLabel(r.files)));
                        var x = el('button', 'cc-x', '✕'); x.type = 'button'; x.title = 'Cancel reply';
                        x.addEventListener('click', function () { setReply(null); });
                        replyBar.appendChild(t); replyBar.appendChild(x);
                        textEl.focus();
                    }
                    function setEdit(r) {
                        setReply(null);
                        editing = r.id;
                        replyBar.hidden = false;
                        var t = el('div', 'cc-rtext');
                        t.appendChild(el('b', '', '✎ Editing message'));
                        t.appendChild(el('span', '', (r.body || '').replace(/\s+/g, ' ').slice(0, 120)));
                        var x = el('button', 'cc-x', '✕'); x.type = 'button'; x.title = 'Cancel edit';
                        x.addEventListener('click', function () { textEl.value = ''; setReply(null); });
                        replyBar.appendChild(t); replyBar.appendChild(x);
                        textEl.value = r.body || '';
                        textEl.focus();
                    }

                    // ---- 📎 pin: camera, photos and videos, audio
                    function drawChips() {
                        chips.textContent = '';
                        chips.hidden = !picked.length;
                        picked.forEach(function (p, i) {
                            var c = el('span', 'cc-chip', ICON[p.kind] + ' ' + p.file.name + ' · ' + size(p.file.size) + ' ');
                            if (!sending) {
                                var x = el('a', 'cc-x', '✕'); x.href = '#'; x.title = 'Remove';
                                x.addEventListener('click', function (e) { e.preventDefault(); picked.splice(i, 1); drawChips(); });
                                c.appendChild(x);
                            }
                            chips.appendChild(c);
                        });
                    }
                    pin.addEventListener('click', function () { menu.hidden = !menu.hidden; });
                    document.addEventListener('click', function (e) {
                        if (!menu.hidden && e.target !== pin && !menu.contains(e.target)) { menu.hidden = true; }
                    });
                    Array.prototype.forEach.call(menu.querySelectorAll('[data-pick]'), function (a) {
                        a.addEventListener('click', function (e) {
                            e.preventDefault(); menu.hidden = true;
                            var input = document.getElementById('ccIn-' + a.getAttribute('data-pick'));
                            input.value = ''; input.click();
                        });
                    });
                    Array.prototype.forEach.call(document.querySelectorAll('.cc-in'), function (input) {
                        input.addEventListener('change', function () {
                            showErr('');
                            Array.prototype.forEach.call(input.files || [], function (f) {
                                var k = kindOf(f);
                                if (!k) { showErr('"' + f.name + '" can not be sent: photos, videos, audio and documents only.'); }
                                else if (f.size > MAX_BYTES) { showErr('"' + f.name + '" is ' + size(f.size) + '. The limit is 50 MB.'); }
                                else if (picked.length >= MAX_FILES) { showErr('At most ' + MAX_FILES + ' files in one message.'); }
                                else { picked.push({ file: f, kind: k }); }
                            });
                            input.value = '';
                            drawChips();
                        });
                    });

                    // ---- send
                    function done(res) {
                        sending = false; btn.disabled = false; btn.innerHTML = ICONS.send; prog.hidden = true;
                        if (res && res.expired) { location.reload(); return; }
                        if (!res || !res.ok) { showErr((res && res.message) || 'Not sent.'); drawChips(); return; }
                        textEl.value = ''; picked = []; drawChips(); setReply(null);
                        shown = ''; draw(res.rows || []); list.scrollTop = list.scrollHeight;
                    }
                    function failed() {
                        sending = false; btn.disabled = false; btn.innerHTML = ICONS.send; prog.hidden = true;
                        drawChips(); showErr('No connection — try again.');
                    }
                    function sendFiles(text) {
                        var fd = new FormData();
                        fd.append('text', text);
                        fd.append('reply_to', replyTo || '');
                        fd.append('who', WHO);
                        picked.forEach(function (p) { fd.append('files', p.file, p.file.name); });
                        var xhr = new XMLHttpRequest();
                        xhr.open('POST', '/kpi/wa/chat/' + T + '/send_files', true);
                        prog.hidden = false; prog.firstElementChild.style.width = '0%'; prog.lastElementChild.textContent = '';
                        xhr.upload.onprogress = function (e) {
                            if (!e.lengthComputable) { return; }
                            var pc = Math.min(100, Math.round(e.loaded / e.total * 100));
                            prog.firstElementChild.style.width = pc + '%';
                            prog.lastElementChild.textContent = pc + '% · ' + size(e.loaded) + ' of ' + size(e.total);
                        };
                        xhr.onload = function () {
                            if (xhr.status === 413) { done({ ok: false, message: 'Too large for the server (max 50 MB).' }); return; }
                            var res = null;
                            try { res = JSON.parse(xhr.responseText); } catch (e) { res = null; }
                            done(res);
                        };
                        xhr.onerror = failed;
                        xhr.send(fd);
                    }
                    function send() {
                        var text = textEl.value.trim();
                        showErr('');
                        if (sending) { return; }
                        if (editing) {
                            if (!text) { textEl.focus(); return; }
                            var id = editing;
                            sending = true; btn.disabled = true; btn.textContent = '…';
                            act(id, 'edit', { text: text }).then(function (ok) {
                                sending = false; btn.disabled = false; btn.innerHTML = ICONS.send;
                                if (ok) { textEl.value = ''; setReply(null); }
                            });
                            return;
                        }
                        if (!text && !picked.length) { textEl.focus(); return; }
                        sending = true; btn.disabled = true; btn.textContent = '…'; drawChips();
                        if (picked.length) { sendFiles(text); return; }
                        var temp = tempRow(text), reply = replyTo;
                        textEl.value = ''; setReply(null);
                        rpc('/send', { text: text, reply_to: reply })
                            .then(function (res) { if (!res || !res.ok) { unsend(temp, text); } done(res); })
                            .catch(function () { unsend(temp, text); failed(); });
                    }
                    btn.addEventListener('click', send);
                    // The box grows with what is typed, up to about five lines.
                    var lastFit = '';
                    function fit() { textEl.style.height = 'auto'; textEl.style.height = Math.min(textEl.scrollHeight, 120) + 'px'; }
                    textEl.addEventListener('input', fit);
                    setInterval(function () { if (textEl.value !== lastFit) { lastFit = textEl.value; fit(); } }, 400);
                    textEl.addEventListener('focus', function () { setTimeout(function () { list.scrollTop = list.scrollHeight; }, 300); });
                    textEl.addEventListener('keydown', function (e) {
                        if (e.key === 'Enter' && !e.shiftKey && window.matchMedia('(pointer:fine)').matches) { e.preventDefault(); send(); }
                    });
                    // 🎤 Voice note, as in WhatsApp: with an empty box the send button is a
                    // mic. Tap it: recording starts. ⏸ pauses (▶ plays what is recorded so far),
                    // 🎙 carries on the same note, 🗑 throws it away, ➤ sends it. Nothing goes
                    // out before ➤.
                    var MIC_SVG = '<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor"><path d="M12 14c1.66 0 2.99-1.34 2.99-3L15 5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5.3-3c0 3-2.54 5.1-5.3 5.1S6.7 14 6.7 11H5c0 3.41 2.72 6.23 6 6.72V21h2v-3.28c3.28-.48 6-3.3 6-6.72h-1.7z"/></svg>';
                    function voiceRecorder(row, txt, sendBtn, hasFiles, sendVoice, say) {
                        var can = !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia && window.MediaRecorder);
                        var mode = 'send', sendHtml = sendBtn.innerHTML;
                        var rec = null, chunks = [], stream = null, mime = '', started = 0, acc = 0, timer = null, bar = null;
                        var tEl, dotEl, pauseBtn, audioEl;
                        function wantMic() { return can && !bar && !sendBtn.disabled && !txt.value.trim() && !hasFiles(); }
                        function refresh() {
                            if (bar) { return; }
                            var m = wantMic() ? 'mic' : 'send';
                            // Which icon shows now: the browser rewrites SVG markup, so look for the
                            // mic's own path rather than comparing the whole string.
                            var isMic = sendBtn.innerHTML.indexOf('M12 14c1.66') > -1;
                            if (m === 'mic' && !isMic) { sendHtml = sendBtn.innerHTML; sendBtn.innerHTML = MIC_SVG; sendBtn.title = 'Record a voice note'; }
                            if (m === 'send' && isMic) { sendBtn.innerHTML = sendHtml; sendBtn.title = 'Send'; }
                            mode = m;
                        }
                        txt.addEventListener('input', refresh);
                        setInterval(refresh, 400);
                        row.addEventListener('click', function (e) {
                            if (mode === 'mic' && !bar && sendBtn.contains(e.target)) { e.preventDefault(); e.stopPropagation(); start(); }
                        }, true);
                        function pickMime() {
                            var c = ['audio/webm;codecs=opus', 'audio/ogg;codecs=opus', 'audio/mp4'];
                            for (var i = 0; i < c.length; i++) { if (MediaRecorder.isTypeSupported && MediaRecorder.isTypeSupported(c[i])) { return c[i]; } }
                            return '';
                        }
                        function fmt(ms) { var s = Math.floor(ms / 1000); return Math.floor(s / 60) + ':' + ('0' + (s % 60)).slice(-2); }
                        function elapsed() { return acc + (rec && rec.state === 'recording' ? Date.now() - started : 0); }
                        function btn(cls, title, html) { var b = el('button', cls); b.type = 'button'; b.title = title; b.innerHTML = html; return b; }
                        function start() {
                            navigator.mediaDevices.getUserMedia({ audio: true }).then(function (s) {
                                stream = s; mime = pickMime(); chunks = []; acc = 0;
                                try { rec = mime ? new MediaRecorder(s, { mimeType: mime }) : new MediaRecorder(s); } catch (e) { rec = new MediaRecorder(s); }
                                rec.ondataavailable = function (ev) { if (ev.data && ev.data.size) { chunks.push(ev.data); } };
                                rec.start(250); started = Date.now();
                                build();
                                timer = setInterval(function () {
                                    if (!bar) { return; }
                                    tEl.textContent = fmt(elapsed());
                                    if (elapsed() >= 900000 && rec.state === 'recording') { pause(); }
                                }, 250);
                            }).catch(function () { say('Microphone not available — allow it in the browser to record.'); });
                        }
                        function build() {
                            bar = el('div', 'cc-rec');
                            var del = btn('cc-rbin', 'Delete', '🗑');
                            dotEl = el('span', 'cc-rdot'); tEl = el('span', 'cc-rtime', '0:00');
                            pauseBtn = btn('cc-rpause', 'Pause', '⏸');
                            audioEl = el('audio'); audioEl.controls = true; audioEl.className = 'cc-raudio'; audioEl.style.display = 'none';
                            var go = btn('cc-rsend', 'Send', ICONS.send);
                            del.addEventListener('click', function () { finish(false); });
                            pauseBtn.addEventListener('click', function () { if (rec.state === 'recording') { pause(); } else { resume(); } });
                            go.addEventListener('click', function () { finish(true); });
                            bar.appendChild(del); bar.appendChild(dotEl); bar.appendChild(tEl); bar.appendChild(audioEl);
                            bar.appendChild(pauseBtn); bar.appendChild(go);
                            row.classList.add('cc-recording'); row.appendChild(bar);
                        }
                        function pause() {
                            if (!rec || rec.state !== 'recording') { return; }
                            rec.pause(); acc += Date.now() - started;
                            dotEl.classList.add('off'); pauseBtn.innerHTML = '🎙'; pauseBtn.title = 'Continue recording';
                            try { rec.requestData(); } catch (e) { /* older browsers: the chunks so far are enough */ }
                            setTimeout(function () {
                                if (!bar) { return; }
                                audioEl.src = URL.createObjectURL(new Blob(chunks, { type: (rec.mimeType || mime || 'audio/webm').split(';')[0] }));
                                audioEl.style.display = ''; tEl.style.display = 'none';
                            }, 200);
                        }
                        function resume() {
                            if (!rec || rec.state !== 'paused') { return; }
                            audioEl.pause(); audioEl.style.display = 'none'; tEl.style.display = '';
                            rec.resume(); started = Date.now();
                            dotEl.classList.remove('off'); pauseBtn.innerHTML = '⏸'; pauseBtn.title = 'Pause';
                        }
                        function finish(send) {
                            if (!rec) { return; }
                            var r = rec;
                            r.onstop = function () {
                                if (stream) { stream.getTracks().forEach(function (t) { t.stop(); }); }
                                clearInterval(timer);
                                var type = (r.mimeType || mime || 'audio/webm').split(';')[0];
                                var ext = type.indexOf('ogg') > -1 ? 'ogg' : (type.indexOf('mp4') > -1 ? 'm4a' : 'webm');
                                var blob = new Blob(chunks, { type: type });
                                if (bar && bar.parentNode) { bar.parentNode.removeChild(bar); }
                                bar = null; rec = null; row.classList.remove('cc-recording'); mode = 'send'; refresh();
                                if (send && blob.size) {
                                    var n = new Date(), p = function (x) { return ('0' + x).slice(-2); };
                                    var name = 'voice-' + n.getFullYear() + p(n.getMonth() + 1) + p(n.getDate()) + '-' + p(n.getHours()) + p(n.getMinutes()) + p(n.getSeconds()) + '.' + ext;
                                    sendVoice(new File([blob], name, { type: type }));
                                }
                            };
                            if (r.state === 'inactive') { r.onstop(); } else { r.stop(); }
                        }
                    }
                    voiceRecorder(document.querySelector('.cc-row'), textEl, btn, function () { return picked.length > 0; },
                        function (f) { picked = [{ file: f, kind: 'audio' }]; drawChips(); send(); }, showErr);
                    load();
                    setInterval(load, 3000);
                })();
